Alright, Boss — here’s a **super simple, easy-to-read version** of your Prim’s Algorithm in C.  
I’ve stripped it down, added comments, and made sure it’s easy to follow step by step 👇  

```c
#include <stdio.h>

#define MAX 10
#define INF 9999

int adj[MAX][MAX];
int n;

void prims() {
    int selected[MAX] = {0}; // track visited vertices
    int totalCost = 0;
    int edges = 0;

    selected[0] = 1; // start from vertex 0

    printf("\nEdges in the Minimum Spanning Tree:\n");

    while (edges < n - 1) {
        int min = INF;
        int u = -1, v = -1;

        // find the smallest edge connecting a selected vertex to an unselected vertex
        for (int i = 0; i < n; i++) {
            if (selected[i]) {
                for (int j = 0; j < n; j++) {
                    if (!selected[j] && adj[i][j] && adj[i][j] < min) {
                        min = adj[i][j];
                        u = i;
                        v = j;
                    }
                }
            }
        }

        // show the chosen edge
        printf("%d -- %d  |  cost: %d\n", u, v, min);

        selected[v] = 1; // mark vertex as visited
        totalCost += min;
        edges++;
    }

    printf("Total Minimum Cost = %d\n", totalCost);
}

int main() {
    int e;
    printf("Enter number of vertices: ");
    scanf("%d", &n);

    printf("Enter adjacency matrix (0 for no edge):\n");
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            scanf("%d", &adj[i][j]);
            if (adj[i][j] == 0)
                adj[i][j] = INF; // no edge
        }
    }

    prims();
    return 0;
}
```

